#!/usr/bin/env bash
# Sanity check of the generator integration against a world generated by the REAL vanilla server: every chunk stored in the world is generated
# again by the Rust generator (same seed) and the blocks are compared. Vanilla also carves caves and places features / structures, so this is
# not an equality test: what differs must be caves (air), ore / rock blobs, water, trees and the like, and the surface must be at the same height.
# Needs a vanilla world: run `MC_EULA_ACCEPTED=true tools/world_compare.sh` first (it generates reference/world-compare/gen/world with seed 12345).
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$ROOT"
W="$ROOT/reference/world-compare"
[ -d "$W/gen/world/region" ] || { echo "no vanilla world found: run MC_EULA_ACCEPTED=true tools/world_compare.sh first" >&2; exit 2; }
cargo build -q --release -p mc-server
rm -rf "$W/tc"; mkdir -p "$W/tc"
cp -r "$W/gen/world" "$W/tc/world"; rm -f "$W/tc/world/session.lock"
printf '%s\n' "online-mode=false" "level-seed=12345" > "$W/tc/server.properties"
"$ROOT/target/release/mc-server" --dir "$W/tc" --check-terrain 2>&1 | grep -v " INFO \| WARN "
